# Surah Al-Isra (chapter 17) — part 6: ayat 51-60 (IDs 2080-2089)
SURAH = 17

ENTRIES = {
2080: (
"یا کوئی اور مخلوق جس کی بڑی عظمت تمہارے سینوں میں ہو — پھر وہ کہتے ہیں ہمیں دوبارہ کون اٹھائے گا؟ کہیے وہی جس نے تمہیں پہلی بار بنایا — پھر وہ آپ کی طرف سر ہلائیں گے اور کہیں گے کب ہو گی؟ کہیے قریب ہی ہوسکتی ہے",
"""۱۔ چاہے پتھر بن جاؤ؛ مگر اس ذات اللہ کا حکم ہے؛ وہی اٹھائے گا؛ قیامت قریب ہے۔
۲۔ ’’أَوْ خَلْقًا مِّمَّا يَكْبُرُ فِي صُدُورِكُمْ فَسَيَقُولُونَ مَن يُعِيدُنَا قُلِ الَّذِي فَطَرَكُمْ أَوَّلَ مَرَّۃٍ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰ أَن يَكُونَ قَرِيبًا‘‘ — یا کوئی اور مخلوق جس کی بڑی عظمت تمہارے سینوں میں ہو — پھر وہ کہتے ہیں ہمیں دوبارہ کون اٹھائے گا؟ کہیے وہی جس نے تمہیں پہلی بار بنایا — پھر وہ آپ کی طرف سر ہلائیں گے اور کہیں گے کب ہو گی؟ کہیے قریب ہی ہوسکتی ہے — یعنی جو چیز بھی مخلوق میں عظیم ہو وہ اٹھائے جانے کی قدرت رکھتی ہے؟ کہہ دو وہی جس نے تمہیں پہلی بار پیدا کیا ہے — پھر وہ آپ کی طرف حیرت سے سر ہلائیں گے اور کہیں گے کب ہو گی؟ کہہ دو قریب ہو سکتی ہے۔
۳۔ عملی سبق: قیامت کی تیاری کرو؛ اللہ قریب سے بہت قریب ہے۔"""
),
2081: (
"جس دن وہ تمہیں بلائے گا تو تم اس کی حمد کرتے ہوئے حاضر ہو جاؤ گے — اور سمجھو گے کہ تم بہت کم مدت رہے",
"""۱۔ قیامت کے دن اللہ کی آواز پر سب اٹھیں گے اور کائنات کی کوئی مصیبت دنیا کی مصیبتوں سے زیادہ ہو گی۔
۲۔ ’’يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا‘‘ — جس دن وہ تمہیں بلائے گا تو تم اس کی حمد کرتے ہوئے حاضر ہو جاؤ گے — اور سمجھو گے کہ تم بہت کم مدت رہے — یعنی جس دن اللہ تمہیں بلائے گا تو تم اس کی حمد کرتے ہوئے حاضر ہو جاؤ گے اور سمجھو گے کہ تم بہت کم مدت رہے۔
۳۔ عملی سبق: دنیا تھوڑی سی زندگی ہے؛ آخرت ہی قائم رہنے والی زندگی ہے۔"""
),
2082: (
"اور میرے بندوں سے کہو کہ وہ بہتر بات کہیں — بے شک شیطان ان کے درمیان فتنہ ڈالتا ہے — بے شک شیطان انسان کا کھلا دشمن ہے",
"""۱۔ شیطان فتنہ ڈالتا ہے؛ مسلمانوں کے لیے ہمیشہ نرم اور بہتر بات کا حکم ہے۔
۲۔ ’’وَقُل لِّعِبَادِي يَقُولُوا الَّتِي هِيَ أَحْسَنُ إِنَّ الشَّيْطَانَ يَنزَغُ بَيْنَهُمْ إِنَّ الشَّيْطَانَ كَانَ لِلْإِنسَانِ عَدُوًّا مُّبِينًا‘‘ — اور میرے بندوں سے کہو کہ وہ بہتر بات کہیں — بے شک شیطان ان کے درمیان فتنہ ڈالتا ہے — بے شک شیطان انسان کا کھلا دشمن ہے — یعنی میرے بندوں سے کہہ دو کہ بہتر بات کہیں — شیطان ان کے درمیان فساد ڈالتا ہے — بے شک شیطان انسان کا کھلا دشمن ہے۔
۳۔ عملی سبق: نرمی سے بات کرو؛ شیطان کی شر سے بچو؛ ہر وقت بھلائی کی گفتگو کرو۔"""
),
2083: (
"آپ کا رب آپ کو بہتر جانتا ہے — اگر وہ چاہے تو تم پر رحم کرے یا اگر چاہے تو عذاب دے — اور ہم نے آپ کو ان پر وکیل بنا کر نہیں بھیجا",
"""۱۔ اللہ ہی سب کو جانتا ہے؛ اس کا اختیار ہے رحم کرے یا سزا؛ نبیؐ صرف پیامبر ہیں۔
۲۔ ’’رَّبُّكُمْ أَعْلَمُ بِكُمْ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ وَمَا أَرْسَلْنَاكَ عَلَيْهِمْ وَكِيلًا‘‘ — آپ کا رب آپ کو بہتر جانتا ہے — اگر وہ چاہے تو تم پر رحم کرے یا اگر چاہے تو عذاب دے — اور ہم نے آپ کو ان پر وکیل بنا کر نہیں بھیجا — یعنی تمہارا رب تمہیں بہتر جانتا ہے — وہ چاہے تو رحم کرے اور چاہے تو عذاب دے — اور ہم نے آپ کو ان پر وکیل بنا کر نہیں بھیجا۔
۳۔ عملی سبق: اللہ کے اختیارات میں دخل نہ دو؛ صرف اپنی ذمہ داری ادا کرو۔"""
),
2084: (
"اور آپ کا رب ان سب کو جانتا ہے جو آسمانوں اور زمین میں ہیں — اور ہم نے بعض نبیوں کو بعض پر فضیلت دی — اور ہم نے داؤدؑ کو زبور دیا",
"""۱۔ نبیوں میں بھی درجات ہیں؛ داؤدؑ کو زبور دیا گیا؛ اللہ کامل ہے۔
۲۔ ’’وَرَبُّكَ أَعْلَمُ بِمَن فِي السَّمَاوَاتِ وَالْأَرْضِ وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَىٰ بَعْضٍ وَآتَيْنَا دَاوُودَ زَبُورًا‘‘ — اور آپ کا رب ان سب کو جانتا ہے جو آسمانوں اور زمین میں ہیں — اور ہم نے بعض نبیوں کو بعض پر فضیلت دی — اور ہم نے داؤدؑ کو زبور دیا — یعنی آپ کا رب ان سب کو جانتا ہے جو آسمانوں اور زمین میں ہیں — ہم نے بعض نبیوں کو بعض پر فضیلت دی — اور داؤدؑ کو زبور عطا کی۔
۳۔ عملی سبق: نبیوں کو ان کے درجات میں مانو؛ زبور اللہ کی کتاب ہے۔"""
),
2085: (
"کہیے انہیں بلاؤ جنہیں تم اللہ کے سوا سمجھتے ہو — وہ تمہاری تکلیف کو دور کرنے کی طاقت نہیں رکھتے اور نہ ہی اسے بدل سکتے ہیں",
"""۱۔ تمام غیر اللہ بے بس ہیں؛ تکلیف دور کرنا ان کے بس میں نہیں؛ مشرکین کی بے بسی۔
۲۔ ’’قُلِ ادْعُوا الَّذِينَ زَعَمْتُم مِّن دُونِهِ فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا‘‘ — کہیے انہیں بلاؤ جنہیں تم اللہ کے سوا سمجھتے ہو — وہ تمہاری تکلیف کو دور کرنے کی طاقت نہیں رکھتے اور نہ ہی اسے بدل سکتے ہیں — یعنی کہہ دو انہیں بلاؤ جنہیں تم اللہ کے سوا سمجھتے ہو — وہ تمہارے نقصان کو دور کرنے کی طاقت نہیں رکھتے اور نہ ہی بدلنے کی۔
۳۔ عملی سبق: اللہ کے سوا کسی کی مدد نہیں؛ صرف اسی کا سہارا لو۔"""
),
2086: (
"جنہیں وہ پکارتے ہیں وہ خود اپنے رب کے قریب ہونے کا وسیلہ تلاش کرتے ہیں — ان میں سے کون قریب تر ہے — اور اس کی رحمت کی امید رکھتے ہیں اور اس کے عذاب سے ڈرتے ہیں — بے شک آپ کے رب کا عذاب ڈرنے والی چیز ہے",
"""۱۔ جن فرشتوں کو پکارتے وہ خود اللہ کے قریب ہونے کی دعا کرتے ہیں؛ اللہ سے امید اور خوف لازم ہیں۔
۲۔ ’’أُولَٰئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ الْوَسِيلَۃَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُ وَيَخَافُونَ عَذَابَهُ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًا‘‘ — جنہیں وہ پکارتے ہیں وہ خود اپنے رب کے قریب ہونے کا وسیلہ تلاش کرتے ہیں — ان میں سے کون قریب تر ہے — اور اس کی رحمت کی امید رکھتے ہیں اور اس کے عذاب سے ڈرتے ہیں — بے شک آپ کے رب کا عذاب ڈرنے والی چیز ہے — یعنی جنہیں وہ پکارتے ہیں وہ اپنے رب کے قریب ہونے کا وسیلہ تلاش کرتے ہیں — کون زیادہ قریب ہے — اور اس کی رحمت کی امید رکھتے ہیں اور اس کے عذاب سے ڈرتے ہیں — بے شک آپ کے رب کا عذاب بہت ڈرنے والی چیز ہے۔
۳۔ عملی سبق: اللہ کے عذاب سے ڈرو اور اس کی رحمت کے امید وار رہو؛ وسیلہ توحید سے۔"""
),
2087: (
"اور کوئی بستی ایسی نہیں مگر یہ کہ ہم اسے قیامت کے دن سے پہلے ہلاک کرنے والے یا سخت عذاب دینے والے ہیں — یہ کتاب میں لکھا ہوا ہے",
"""۱۔ ہر بستی کا انجام تباہی یا عذاب؛ یہ اللہ کی تقدیر میں ہے؛ اس سے کوئی چھٹکارا نہیں۔
۲۔ ’’وَإِن مِّن قَرْيَۃٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ الْقِيَامَۃِ أَوْ مُعَذِّبُوهَا عَذَابًا شَدِيدًا كَانَ ذَٰلِكَ فِي الْكِتَابِ مَسْطُورًا‘‘ — اور کوئی بستی ایسی نہیں مگر یہ کہ ہم اسے قیامت کے دن سے پہلے ہلاک کرنے والے یا سخت عذاب دینے والے ہیں — یہ کتاب میں لکھا ہوا ہے — یعنی کوئی بستی ایسی نہیں جسے ہم قیامت سے پہلے ہلاک نہ کریں یا اسے سخت عذاب نہ دیں — یہ کتاب میں لکھا ہوا ہے۔
۳۔ عملی سبق: اللہ کا فیصلہ حتمی ہے؛ تکبر اور سرکشی کا انجام تباہی ہے۔"""
),
2088: (
"اور ہم نے معجزات بھیجنے سے اس لیے روکا ہے کہ پہلے لوگ انہیں جھٹلا چکے — اور ہم نے ثمود کو اونٹنی واضح معجزہ کے طور پر دی — مگر انہوں نے اس کے ساتھ ظلم کیا — اور ہم معجزات صرف ڈرانے کے لیے بھیجتے ہیں",
"""۱۔ ثمود کی اونٹنی — واضح نشانی؛ مگر اسے جھٹلایا اور ظلم کیا؛ معجزات ڈرانے کے لیے ہوتے ہیں الزام لگانے کے لیے نہیں۔
۲۔ ’’وَمَا مَنَعَنَا أَن نُّرْسِلَ بِالْآيَاتِ إِلَّا أَن كَذَّبَ بِهَا الْأَوَّلُونَ وَآتَيْنَا ثَمُودَ النَّاقَۃَ مُبْصِرَۃً فَظَلَمُوا بِهَا وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا‘‘ — اور ہم نے معجزات بھیجنے سے اس لیے روکا ہے کہ پہلے لوگ انہیں جھٹلا چکے — اور ہم نے ثمود کو اونٹنی واضح معجزہ کے طور پر دی — مگر انہوں نے اس کے ساتھ ظلم کیا — اور ہم معجزات صرف ڈرانے کے لیے بھیجتے ہیں — یعنی ہم نے معجزات بھیجنے سے اس لیے روکا کہ پہلے والے انہیں جھٹلا چکے — ہم نے ثمود کو اونٹنی واضح نشانی کے طور پر دی مگر انہوں نے اس پر ظلم کیا — اور ہم معجزات صرف ڈرانے کے لیے بھیجتے ہیں۔
۳۔ عملی سبق: معجزات پر ایمان لاؤ؛ نشانیوں کی بے حیائی سے بچو۔"""
),
2089: (
"اور جب ہم نے آپ سے کہا تھا کہ آپ کے رب نے تمام لوگوں کو گھیر رکھا ہے — اور وہ خواب جو ہم نے آپ کو دکھایا وہ لوگوں کے لیے صرف آزمائش تھی — اور قرآن میں لعنت کی گئی درخت بھی — اور ہم انہیں ڈراتے ہیں مگر انہیں اور بھی سرکشی کے سوا کچھ نہیں بڑھاتا",
"""۱۔ معراج کا خواب لوگوں کے لیے فتنہ بنا؛ زقوم کا درخت — جہنم کی خوراک؛ منکرین کی سرکشی مٹا دیتا ہے۔
۲۔ ’’وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِالنَّاسِ وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلَّا فِتْنَۃً لِّلنَّاسِ وَالشَّجَرَۃَ الْمَلْعُونَۃَ فِي الْقُرْآنِ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَانًا كَبِيرًا‘‘ — اور جب ہم نے آپ سے کہا تھا کہ آپ کے رب نے تمام لوگوں کو گھیر رکھا ہے — اور وہ خواب جو ہم نے آپ کو دکھایا وہ لوگوں کے لیے صرف آزمائش تھی — اور قرآن میں لعنت کی گئی درخت بھی — اور ہم انہیں ڈراتے ہیں مگر انہیں اور بھی سرکشی کے سوا کچھ نہیں بڑھاتا — یعنی جب ہم نے آپ سے کہا تھا کہ آپ کا رب تمام لوگوں کو گھیرے ہوئے ہے — اور وہ خواب جو ہم نے آپ کو دکھایا وہ لوگوں کے لیے آزمائش تھا — اور قرآن میں لعنت کی گئی درخت — ہم انہیں ڈراتے ہیں مگر ان کی سرکشی میں اضافہ ہی ہوتا ہے۔
۳۔ عملی سبق: اللہ کی نشانیوں سے سبق سیکھو؛ سرکشی ایمان کو ختم کر دیتی ہے۔"""
),
}
